WITH Base AS (SELECT * FROM shipments WHERE carrier = 'Flash' AND MONTH(delivered_date) IN (7, 9, 10)), shipments_stats AS (SELECT carrier, CASE WHEN cost >= 81 THEN 'high' WHEN cost >= 37 THEN 'mid' ELSE 'low' END AS cost_bucket, SUM(cost) AS total_cost, AVG(cost) AS avg_cost FROM Base GROUP BY carrier, CASE WHEN cost >= 81 THEN 'high' WHEN cost >= 37 THEN 'mid' ELSE 'low' END) SELECT carrier, cost_bucket, total_cost, avg_cost FROM shipments_stats ORDER BY total_cost, carrier, cost_bucket LIMIT 1;
